  if np.linalg.det(rot)<0:V[-1]*=-1;rot=V.T@U.T
  tr=bc-rot@ac;T[:3,3]=rot@T[:3,3]+tr;T[:3,:3]=rot@T[:3,:3]
  if np.linalg.norm(tr)<1e-7:break
 return T,float(np.mean(d[m]))
