def tip_pixels(o):
 from scipy.ndimage import label
 out={}
 for c in cams:
  a=o.last[c].astype(float);p=cloud(o,c);m=(a[:,:,1]>1.4*a[:,:,0])&(a[:,:,1]>1.4*a[:,:,2])&(a[:,:,1]>80)&(p[:,:,0]<-.22)&(p[:,:,2]>.3)&(p[:,:,2]<.65)
  ll,n=label(m);out[c]=[]
  for i in range(1,n+1):
   v,u=np.where(ll==i)
   if len(v)>1:out[c].append([float(u.mean()),float(v.mean()),len(v)])
 return out
def ray(o,c,uv):
 C=np.array(o.meta['cameras'][c]['cam2world_gl']);K=np.array(o.meta['cameras'][c]['intrinsic_cv']);u,v=uv[:2];d=C[:3,:3]@[(u-160)/K[0,0],-(v-120)/K[1,1],-1];return C[:3,3],d/np.linalg.norm(d)
def triang(o,c,u,cc,v):
 p,d=ray(o,c,u);pp,dd=ray(o,cc,v);ds=np.linalg.lstsq(np.stack([d,-dd],axis=1),pp-p,rcond=None)[0];a=p+ds[0]*d;b=pp+ds[1]*dd;return (a+b)/2,np.linalg.norm(a-b)
